import json, sys, html as _h

BOOK = {'title': 'Shadows of Victorian London', 'author': 'Signature original', 'genre': 'Medieval Quests', 'chapters': [{'n': 1, 'title': 'The Discovery', 'text': "By morning Thomas Beckett had decided. a will would not stay hidden. Whatever the disgraced lord did, whatever Victorian London whispered — courage in every age, and the truth would have its day.\n\nThe a will came to Thomas Beckett on a rainy Thursday in Victorian London, tucked in a solicitor's envelope smelling of dust and secrets. Thomas Beckett was not, by nature, a curious person. Curiosity, in Victorian London, was a luxury for those with full larders.\n\nBut a will would not be ignored. That night, by gaslight, Thomas Beckett examined it: the handwriting, the seal, the date — twenty years gone. And the name. The name that the disgraced lord had paid good money to bury."}, {'n': 2, 'title': 'Inquiries', 'text': "Each answer was a thread, and the threads wove the disgraced lord's tapestry: the mill, the accident, the silenced witnesses, the money that flowed like a dirty river through Victorian London. a will was the loose end.\n\nThe daguerreotype — no, a will — revealed its last secret then: a face in the background, a witness the disgraced lord had missed. Thomas Beckett found the address. The game, as the young people say, was afoot — though in Victorian London, they said it more politely.\n\nthe disgraced lord noticed. A carriage followed Thomas Beckett home. A note arrived: 'Some things are better left buried.' Thomas Beckett burned the note and kept digging. Buried things, Thomas Beckett had learned, have a way of surfacing."}, {'n': 3, 'title': 'The Witness', 'text': "The witness lived in Victorian London's poorest court, old and afraid and tired of being afraid. a will in Thomas Beckett's hands loosened their tongue: yes, they had seen. Yes, they would swear. No, they had never dared.\n\nthe disgraced lord struck that night: a break-in, a fire set to frighten, a thug with a message written in bruises. the old soldier took the worst of it and joked through split lips. Thomas Beckett wept and planned.\n\nThe magistrate was the disgraced lord's man; the papers were the disgraced lord's papers. But a will was Thomas Beckett's, and the witness was real, and the truth — Thomas Beckett clung to this — the truth is stubborn in any century."}, {'n': 4, 'title': 'The Reckoning', 'text': "The magistrate squirmed. The crowd — Victorian London's people, mill hands and merchants' wives — began to murmur, and the murmur became a voice. the disgraced lord's money couldn't buy this room. Not tonight.\n\nIt came to a head at the assembly rooms, in front of all Victorian London: Thomas Beckett stood and spoke, with a will held high and the witness beside them. The gaslight seemed to lean in to listen.\n\nthe disgraced lord was taken — quietly, for the family's sake, but taken. The mill was sold. The debts were paid. The witness wept with relief, and the old soldier's bruises became badges."}, {'n': 5, 'title': 'Restoration', 'text': "the old soldier married the vicar's son — or daughter; Victorian London gossiped happily either way — and named their first child after Thomas Beckett, who pretended to mind and didn't.\n\ncourage in every age — Thomas Beckett had it carved, finally, on no monument at all, just lived it, in Victorian London, in every ordinary, extraordinary day.\n\nYears later, Thomas Beckett would show a will to the curious and say: 'This is what courage looks like when it's old and paper.' And the young would listen, and Victorian London would remember."}, {'n': 6, 'title': 'Coda: The Drawer', 'text': "The gaslight is electric now. The carriages are cars. But a will is still a will, and Thomas Beckett is still Thomas Beckett, and the drawer still opens.\n\nthe old soldier visits with the children, who are told the story as a fairy tale — which, Thomas Beckett reflects, is what all true stories become, if they're lucky.\n\nthe disgraced lord is a name in the records, a caution. Victorian London is a place where the mills run fair and the magistrate is honest, mostly, which is as much as any age can ask."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

